INSERT INTO public."products" ("id", "name", "slug", "description", "price", "original_price", "category", "category_slug", "images", "stock", "sku", "vendor_id", "status", "featured", "tags", "rating", "review_count", "sold_count", "created_at", "updated_at", "brand", "nameBn", "descriptionBn", "isNewArrival", "isBestSeller", "discountPercent", "regularPrice", "sellingPrice", "oldPrice", "stockQuantity", "stockStatus", "featuredImage", "isActive", "isFeatured", "sizes", "colors", "shortDescription", "fts", "approval_status", "attributes", "variants", "embedding")
VALUES
  ('8010e7ac-ab9c-4386-9735-dd465e406cef', 'Awei T50', 'awei-t50', '<div style="font-family:Arial,sans-serif; color:#222; line-height:1.8; max-width:1000px; margin:auto;">

  <!-- Header -->
  <div style="text-align:center; padding:30px; background:#f5f5f7; border-radius:15px;">
    <h1 style="font-size:34px; margin-bottom:10px;">Awei T50</h1>
    <p style="font-size:16px; color:#555;">
      True Wireless Bluetooth Earbuds with ENC, Deep Bass & Gaming Mode
    </p>
  </div>

  <!-- Product Description -->
  <div style="padding:25px 10px;">
    <h2 style="font-size:26px;">Product Description</h2>

    <p>
      The Awei T50 is a stylish and budget-friendly true wireless earbud designed for immersive music,
      gaming, and everyday communication. Powered by Bluetooth 5.3 technology, it ensures stable connectivity,
      faster pairing, and low-latency wireless performance.
    </p>

    <p>
      Equipped with large dynamic drivers, the earbuds deliver rich bass, balanced mids,
      and clear vocals for an enjoyable listening experience across music, videos, and games.
      The low-latency gaming mode improves audio synchronization for smoother gameplay.
    </p>

    <p>
      With ENC (Environmental Noise Cancellation) support and built-in microphones,
      the Awei T50 provides clearer voice calls by reducing surrounding background noise.
      Its ergonomic semi in-ear design ensures comfortable long-term usage.
    </p>

    <p>
      Featuring IPX6 water resistance, touch controls, Type-C fast charging,
      and extended battery backup using the charging case, the Awei T50 is perfect for workouts,
      travel, gaming, and daily entertainment.
    </p>
  </div>

  <!-- Key Features -->
  <div style="padding:10px;">
    <h2 style="font-size:26px;">Key Features</h2>

    <ul style="padding-left:20px; color:#444;">
      <li>Bluetooth 5.3 Fast & Stable Connectivity</li>
      <li>Hi-Fi Stereo Sound with Deep Bass</li>
      <li>Low Latency Gaming Mode</li>
      <li>ENC Noise Reduction for Clear Calls</li>
      <li>IPX6 Water & Sweat Resistance</li>
      <li>Smart Touch Controls</li>
      <li>USB Type-C Fast Charging</li>
      <li>Compact & Lightweight Design</li>
    </ul>
  </div>

  <!-- Specification Table -->
  <div style="margin-top:20px;">
    <h2 style="font-size:26px;">Specifications</h2>

    <table style="width:100%; border-collapse:collapse; font-size:15px;">
      <tr style="background:#111; color:#fff;">
