  ('session_1778301473630_9aggrcfdg', '[{"product":{"_id":"3c363981-63c9-4251-a459-8495655f6c5d","name":"MEMO DL05","slug":"memo-dl05","image":"data:image/jpeg;base64,","price":1300,"rating":5,"inStock":true,"category":"Mobile Cooler","discount":13,"description":"<div style=\"font-family:Arial,sans-serif; color:#222; line-height:1.8; max-width:1000px; margin:auto;\">\n\n  <!-- Header -->\n  <div style=\"text-align:center; padding:30px; background:#f5f5f7; border-radius:15px;\">\n    <h1 style=\"font-size:34px; margin-bottom:10px;\">MEMO DL05</h1>\n    <p style=\"font-size:16px; color:#555;\">\n      Advanced Semiconductor Mobile Phone Cooler for Gaming Performance\n    </p>\n  </div>\n\n  <!-- Description -->\n  <div style=\"padding:25px 10px;\">\n    <h2 style=\"font-size:26px;\">Product Description</h2>\n\n    <p>\n      The MEMO DL05 is a powerful mobile cooling device designed specifically for gamers who face overheating issues during long gameplay sessions.\n      It uses advanced semiconductor (Peltier-based) cooling technology to instantly reduce device temperature.\n    </p>\n\n    <p>\n      With its strong cooling performance, it helps maintain stable FPS and prevents lag caused by thermal throttling.\n      This ensures smooth gameplay in PUBG, Free Fire, Call of Duty Mobile, and other high-performance games.\n    </p>\n\n    <p>\n      The DL05 features a durable build with aluminum heat dissipation, RGB lighting effects, and a compact design for easy portability.\n      It operates quietly, making it ideal for uninterrupted gaming or streaming.\n    </p>\n\n    <p>\n      Designed with universal compatibility, it supports most smartphones and provides efficient cooling even during charging and heavy usage.\n    </p>\n  </div>\n\n  <!-- Key Features -->\n  <div style=\"padding:10px;\">\n    <h2 style=\"font-size:26px;\">Key Features</h2>\n\n    <ul style=\"padding-left:20px; color:#444;\">\n      <li>Semiconductor (Peltier) Cooling Technology</li>\n      <li>Rapid Temperature Reduction Performance</li>\n      <li>Stable FPS for Mobile Gaming</li>\n      <li>RGB Gaming Lighting Effects</li>\n      <li>Silent Low-Noise Operation</li>\n      <li>Type-C Power Input</li>\n      <li>Universal Smartphone Compatibility</li>\n      <li>Lightweight & Portable Design</li>\n    </ul>\n  </div>\n\n  <!-- Specification Table -->\n  <div style=\"margin-top:20px;\">\n    <h2 style=\"font-size:26px;\">Specifications</h2>\n\n    <table style=\"width:100%; border-collapse:collapse; font-size:15px;\">\n      <tr style=\"background:#111; color:#fff;\">\n        <th style=\"padding:12px; text-align:left;\">Feature</th>\n        <th style=\"padding:12px; text-align:left;\">Details</th>\n      </tr>\n\n      <tr>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Model</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">MEMO DL05</td>\n      </tr>\n\n      <tr style=\"background:#f9f9f9;\">\n        <td style=\"padding:10px; border:1px solid #ddd;\">Cooling Type</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Semiconductor (Peltier) Cooling</td>\n      </tr>\n\n      <tr>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Power Input</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">5V / 1.5A–2A</td>\n      </tr>\n\n      <tr style=\"background:#f9f9f9;\">\n        <td style=\"padding:10px; border:1px solid #ddd;\">Interface</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Type-C</td>\n      </tr>\n\n      <tr>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Fan Speed</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Up to 7500 RPM</td>\n      </tr>\n\n      <tr style=\"background:#f9f9f9;\">\n        <td style=\"padding:10px; border:1px solid #ddd;\">Material</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">ABS + Aluminum Alloy</td>\n      </tr>\n\n      <tr>\n        <td style=\"padding:10px; border:1px solid #ddd;\">Lighting</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">RGB LED Effects</td>\n      </tr>\n\n      <tr style=\"background:#f9f9f9;\">\n        <td style=\"padding:10px; border:1px solid #ddd;\">Compatibility</td>\n        <td style=\"padding:10px; border:1px solid #ddd;\">65–85mm Smartphone Width</td>\n      </tr>\n\n    </table>\n  </div>\n\n</div>","reviewCount":0,"originalPrice":1500},"quantity":3}]'::jsonb, '2026-05-09T04:38:03.758872+00:00'),
