  ('user_13e05f5e-2e48-4c84-ab5b-ba9d75ac7373', '[{"product":{"id":"4373bf9f-6ba6-4352-9761-a762cd8d2886","sku":null,"name":"Handmade Silk Kundan Churi Bangle Set | Golden & Purple Bangles","slug":"handmade-silk-kundan-churi-bangle-set-golden-purple-bangles-muk4n6j5","tags":[],"brand":"","price":499,"stock":10,"images":["https://res.cloudinary.com/do56bvtzt/image/upload/v1791538883/stellar-mart/migrated/axaeyvdsyppuel3mwdy0.jpg"],"nameBn":"Handmade Silk Kundan Churi Bangle Set | Golden & Purple Bangles","rating":0,"vendor":{"id":"official","rating":4.9,"logo_url":"/logo.png","shop_name":"StellarMart Official","owner_name":"StellarMart","is_official":true,"is_verified":true,"fulfilled_by":"Stellar Direct","shop_address":"Dhaka, Bangladesh (Official Warehouse)","response_rate":"100%","total_reviews":1250,"on_time_delivery":"99.9%","verification_badge":"Official Mall"},"category":"28f066f0-8799-476c-b24f-30df7977e9a9","isActive":true,"oldPrice":600,"variants":[],"vendor_id":null,"attributes":[],"created_at":"2026-09-27T18:03:24.224513","isFeatured":true,"sold_count":2,"store_name":"StellarMart Official","description":"<h2>Handmade Silk Kundan Churi Bangle Set – Golden &amp; Purple</h2>\n\n<p>\nAdd a royal touch to your ethnic jewelry collection with this\n<strong>Handmade Silk Kundan Churi Bangle Set</strong>. Crafted with premium\nsilk thread and elegant Kundan stone detailing, this beautiful set combines\ntraditional craftsmanship with a luxurious contemporary appearance.\n</p>\n\n<p>\nThe rich <strong>golden yellow and deep purple</strong> color combination\ncreates a bold yet graceful look that beautifully complements sarees,\nlehengas, salwar suits, and other traditional outfits. The intricate\nleaf-inspired and geometric Kundan motifs add an elegant decorative touch.\n</p>\n\n<p>\nEach bangle is carefully <strong>handcrafted by skilled artisans</strong>.\nThe smooth silk thread finish makes the bangles lightweight and comfortable,\nallowing you to wear them for long hours during weddings, festivals, and\nspecial celebrations.\n</p>\n\n<h3>✨ Key Features</h3>\n<ul>\n  <li>Handmade silk Kundan churi bangle set</li>\n  <li>Premium silk thread with detailed Kundan work</li>\n  <li>Rich golden yellow and deep purple color combination</li>\n  <li>Beautiful leaf-inspired and geometric Kundan motifs</li>\n  <li>Lightweight and comfortable for extended wear</li>\n  <li>Smooth and skin-friendly silk thread finish</li>\n  <li>Ideal for bridal, wedding and festive occasions</li>\n  <li>Durable finish with attractive long-lasting shine</li>\n  <li>Suitable for traditional and ethnic outfits</li>\n</ul>\n\n<h3>📋 Product Specifications</h3>\n<table>\n  <tr>\n    <th>Product Type</th>\n    <td>Silk Kundan Churi Bangle Set</td>\n  </tr>\n  <tr>\n    <th>Material</th>\n    <td>Silk Thread &amp; Kundan Stones</td>\n  </tr>\n  <tr>\n    <th>Color</th>\n    <td>Golden Yellow &amp; Deep Purple</td>\n  </tr>\n  <tr>\n    <th>Design</th>\n    <td>Leaf-Inspired &amp; Geometric Kundan Motifs</td>\n  </tr>\n  <tr>\n    <th>Finish</th>\n    <td>Smooth Silk Thread Finish</td>\n  </tr>\n  <tr>\n    <th>Style</th>\n    <td>Traditional, Royal &amp; Ethnic</td>\n  </tr>\n  <tr>\n    <th>Handmade</th>\n    <td>Yes</td>\n  </tr>\n  <tr>\n    <th>Occasion</th>\n    <td>Wedding, Haldi, Mehndi, Puja, Festival, Reception &amp; Cultural Events</td>\n  </tr>\n</table>\n\n<h3>🎉 Perfect For</h3>\n<p>\nPerfect for brides, bridesmaids, wedding guests, festive wear lovers, and anyone\nlooking to add a royal ethnic touch to their traditional outfit. It also makes\na beautiful premium gift for special occasions.\n</p>\n\n<h3>👗 Styling</h3>\n<p>\nPair these golden and purple Kundan bangles with sarees, lehengas, salwar suits,\nor other traditional outfits to create an elegant and luxurious festive look.\n</p>","is_official":true,"stockStatus":"in_stock","isBestSeller":false,"isNewArrival":true,"regularPrice":600,"review_count":0,"sellingPrice":499,"featuredImage":"https://res.cloudinary.com/do56bvtzt/image/upload/v1791538881/stellar-mart/migrated/uwnddyxhygitn11e8zpr.jpg","stockQuantity":10,"shortDescription":"Handmade Silk Kundan Churi Bangle Set featuring a rich golden yellow and deep purple color combination with elegant Kundan detailing. Lightweight, comfortable, and perfect for bridal wear, weddings, haldi, mehndi, puja, festivals, receptions, and traditional celebrations."},"quantity":1,"variantSku":null,"variantData":null,"variantPrice":499}]'::jsonb, '2026-10-23T19:02:16.982692+00:00'),
